/* Senior-level depth pack: every Senior Level menu item reaches a minimum of 30 experience-based questions. */
var defined_sections = defined_sections || {};

(function () {
  function seniorQuestion(id, category, topic, prompt, answer, experience, tradeoff) {
    return {
      id: id,
      category: category,
      topic: topic,
      subtopic: 'Senior interview practice',
      question: prompt,
      whyAsked: 'Interviewers use this to check whether you can make a sound quality decision, explain its trade-offs, and own the outcome in a real delivery environment.',
      difficulty: 4,
      importance: 'must',
      interviewType: 'Senior Interview',
      thirtySecAnswer: answer,
      interviewAnswer: '**Senior answer:** ' + answer + '\n\n**Experience framing:** ' + experience + '\n\n**Decision lens:** ' + tradeoff,
      detailedExplanation: '**Strong structure:** State the business impact, explain your approach, show the evidence you used, and finish with the measurable result.\n\n**What interviewers listen for:** Risk ownership, practical prioritization, clear communication, and a solution that is maintainable by the whole team.',
      simpleExplanation: answer,
      realWorldExample: 'Use a genuine project example with enough context to show the scale, the risk, and the result without exposing confidential details.',
      projectExample: experience,
      experienceNote: 'Speak in first person: explain the situation, the action you personally drove, and the result you measured.',
      codeCommand: '',
      expectedOutput: '',
      followUpQ: 'What evidence would make you change that decision?',
      followUpA: 'I would revisit the decision when production signals, risk level, cost, delivery timeline, or stakeholder requirements materially change.',
      seniorFollowUpQ: 'How would you make this approach repeatable across teams?',
      seniorFollowUpA: 'I would turn the lesson into a lightweight standard, automation or template, measurable quality signal, and an explicit ownership model.',
      commonMistake: 'Giving a textbook definition without naming the risk, trade-off, or evidence behind the decision.',
      bestPractice: 'Answer with a credible example and quantify the impact whenever possible.'
    };
  }

  function ensureThirty(sectionKey, idPrefix, category, items) {
    var section = defined_sections[sectionKey];
    if (!section) throw new Error('Missing Senior Level section: ' + sectionKey);
    var needed = Math.max(0, 30 - (section.questions || []).length);
    for (var index = 0; index < needed; index++) {
      var item = items[index];
      if (!item) throw new Error('Not enough depth prompts for ' + sectionKey);
      section.questions.push(seniorQuestion(
        idPrefix + String(index + 1).padStart(3, '0'),
        category,
        item[0],
        item[1],
        item[2],
        item[3],
        item[4]
      ));
    }
  }

  ensureThirty('senior-scenarios', 'SNR', 'Senior QA', [
    ['Automation strategy', 'How do you create an automation strategy for a new product?', 'Start with product risk, architecture, release cadence, and feedback needs. Build the smallest layered suite that protects critical journeys, then scale only where the return is clear.', 'On a new B2B platform, I started with API contracts and ten revenue-critical UI checks before adding broad regression coverage. That gave the team PR feedback in under ten minutes.', 'Balance early confidence with maintenance cost; do not begin by automating every manual test.'],
    ['Risk-based testing', 'How do you prioritize testing when there is not enough time?', 'Rank work by customer impact, likelihood of failure, recent change, integration complexity, and detectability. Test the highest-risk paths first and state the residual risk clearly.', 'Before a release with one day available, I focused on payment, login, permissions, and data migration paths, then shared the untested lower-risk scope with product and engineering.', 'The goal is an informed release decision, not an unrealistic claim of complete coverage.'],
    ['Test estimation', 'How do you estimate testing for an unfamiliar feature?', 'Break the work into analysis, test design, data and environment setup, execution, automation, defect retest, and dependencies. Give a range with assumptions and contingency.', 'For an unfamiliar third-party integration, I gave a range after identifying sandbox availability and contract stability as the main unknowns; the estimate became firmer after a short spike.', 'A precise estimate without assumptions is less useful than a transparent range with risk drivers.'],
    ['Release decision', 'What do you do when a high-severity defect is found before release?', 'Confirm reproducibility and user impact, assess scope and workaround, gather the accountable owners, present options, and document the risk-based decision. QA supplies evidence; the business owns the go or no-go call.', 'In one release, we used a feature flag to isolate the affected flow, validated the unaffected critical path, and agreed a monitored partial release with a committed fix window.', 'Do not make a release decision alone or hide risk behind an overall pass percentage.'],
    ['Production incident', 'How do you respond to a production issue caused by a missed scenario?', 'Stabilize the customer impact first, preserve evidence, help identify root cause, and then add prevention at the right layer—unit, API, UI, monitoring, or process.', 'After an escaped permissions defect, I partnered with engineering to add an API authorization matrix, a targeted UI smoke test, and a release checklist item for role changes.', 'Avoid blame and avoid adding a slow end-to-end test if a faster contract check would prevent recurrence.'],
    ['Flaky tests', 'How do you reduce a high flaky-test rate?', 'Measure failures across repeat runs, classify root causes, fix synchronization and data isolation first, quarantine only when necessary, and track the rate weekly.', 'I reduced a suite from about 18% flaky to under 3% by replacing sleeps, making data unique per test, and retaining screenshots and logs for every retry.', 'Retries are diagnostic signals, not a definition of reliability.'],
    ['Regression optimization', 'How do you reduce a four-hour regression suite without reducing quality?', 'Remove duplicate checks, shift stable logic down to API or unit layers, parallelize isolated tests, and maintain a risk-based smoke tier. Measure execution time and defect detection before and after.', 'I moved setup-heavy UI assertions to API contracts and introduced parallel execution, reducing a nightly suite from four hours to 70 minutes while keeping escaped-defect trend stable.', 'Fast feedback must retain meaningful risk coverage; speed alone is not optimization.'],
    ['Quality metrics', 'Which quality metrics would you present to leadership?', 'Present a small narrative set: release risk, requirement and risk coverage, escaped defects, defect aging, automation health, flaky rate, cycle time, and production reliability.', 'I used a one-page release dashboard that paired pass trend with open critical risk and the decision needed from stakeholders.', 'Avoid vanity counts such as number of test cases or automation percentage without outcome context.'],
    ['Test data', 'How do you design test data for parallel automation?', 'Use isolated, unique, self-service data; create it through APIs where possible; record ownership; and clean it up deterministically.', 'I introduced UUID-based data builders and API setup, which removed shared-account collisions and allowed the suite to run safely across five workers.', 'Do not rely on a few permanent shared accounts for a parallel suite.'],
    ['CI/CD strategy', 'What should run on pull request, deployment, and nightly pipelines?', 'Run fast compilation, unit, static checks, contracts, and stable smoke tests on pull request; deploy validation on release; and broader cross-browser or exploratory-supporting regression at night.', 'I split one monolithic Jenkins job into PR, deploy, and nightly stages, which made failures actionable and reduced developer feedback time significantly.', 'Pipelines should serve feedback speed and risk, not run every test on every event.'],
    ['Production observability', 'How do monitoring and synthetic checks complement automation?', 'Automation proves expected behavior before release; observability detects real-user and dependency conditions after release. Use logs, metrics, traces, alerts, and small synthetic flows together.', 'For a login service, I added a synthetic authentication check with alerting and correlated it with API latency dashboards after a production outage.', 'Do not treat production monitoring as a replacement for pre-release testing.'],
    ['Mentoring', 'How do you mentor a junior QA engineer?', 'Assess the specific gap, pair on real work, give a clear rubric, transfer ownership gradually, and measure improvement through independent delivery and better-quality feedback.', 'I paired a junior engineer on locator strategy and failure triage, then had them own a small smoke area and present the stability trend to the team.', 'Mentoring is not doing their work; it is building repeatable confidence and ownership.'],
    ['Code review', 'What do you look for in an automation code review?', 'I check intent, test isolation, stable locators, meaningful assertions, data cleanup, waits, diagnostics, naming, and whether the test belongs at the correct layer.', 'I introduced a short review checklist that caught fixed sleeps and shared data before merge, reducing avoidable flaky failures.', 'Review for maintainability and risk reduction, not only formatting.'],
    ['Stakeholder conflict', 'How do you handle disagreement about release quality?', 'Bring observable evidence, frame the customer and business impact, clarify the decision owner, offer mitigation options, and document the accepted risk.', 'When product wanted to release despite an unresolved defect, I demonstrated the affected customer path, estimated exposure, and proposed a feature-flag mitigation that both sides accepted.', 'Avoid arguing from opinion or using QA as a veto without evidence.'],
    ['Technical debt', 'How do you make automation technical debt visible?', 'Convert debt into specific risks and costs: flaky rate, long execution, slow triage, duplicate coverage, unsupported libraries, or blocked releases. Rank and fund it like product work.', 'I created a debt backlog tied to failure analytics and reserved a small capacity allocation each sprint; our mean triage time improved visibly.', 'A vague statement that the framework is messy will not attract investment.'],
    ['Test environments', 'How do you manage unstable or shared test environments?', 'Separate product defects from environment issues with health checks, known-data validation, ownership, logs, and clear escalation. Use disposable or isolated environments where the risk justifies it.', 'We added a pre-suite environment health gate that checked dependencies and seed data, preventing hours of false automation failures.', 'Do not silently rerun failing tests when the environment is unhealthy.'],
    ['Integration testing', 'How do you test a feature with several external dependencies?', 'Map contracts, failure modes, ownership, and data flow; use service virtualization for controlled negative cases; retain a small real-integration suite; and monitor dependencies after release.', 'For a payment integration, we tested timeouts and malformed callbacks with stubs, then retained a sandbox smoke check for the real provider.', 'Pure mocks miss integration reality; pure end-to-end testing is often slow and fragile.'],
    ['Cross-browser strategy', 'How do you choose a cross-browser coverage matrix?', 'Use product analytics, customer commitments, device risk, and change type to choose representative browsers and devices. Run the full matrix on release candidates, not necessarily every pull request.', 'I reduced a costly matrix to high-traffic combinations on PRs and ran the expanded matrix overnight and before major releases.', 'A maximum matrix without prioritization consumes time without improving decisions.'],
    ['Scalability', 'How do you scale an automation platform across multiple teams?', 'Standardize the foundations—configuration, reporting, secrets, test data, conventions, and quality gates—while allowing product teams ownership of their domain tests.', 'I created reusable starter modules and documentation so two product teams could adopt the same reporting and driver lifecycle without copying a monolithic framework.', 'Central standards should enable teams, not become a bottleneck.'],
    ['Architecture', 'How do you decide whether a check belongs in unit, API, UI, or monitoring?', 'Place the check at the lowest layer that provides confidence in the risk. Use UI for critical user journeys, APIs for contracts and data flows, units for logic, and monitoring for real production behavior.', 'I moved validation-heavy UI tests into service-level tests and kept only the user-critical browser journeys, improving speed and diagnosis.', 'The UI layer is not the default answer for every requirement.'],
    ['Shift-left', 'How have you implemented shift-left quality practices?', 'Join refinement, make acceptance criteria testable, review API contracts, encourage unit and component coverage, and provide fast PR feedback.', 'I introduced a refinement checklist that exposed missing error states before development and reduced late-cycle clarification defects.', 'Shift-left is a team behavior, not QA writing tests earlier in isolation.'],
    ['Shift-right', 'How do you use shift-right testing safely?', 'Use feature flags, canaries, telemetry, synthetic checks, and rollback criteria to learn from real conditions without exposing all customers to unmanaged risk.', 'For a high-impact search change, we released to a small cohort, watched latency and conversion signals, and expanded only after the health criteria held.', 'Production experimentation needs guardrails, privacy review, and an explicit rollback plan.'],
    ['Security and privacy', 'What is QA’s role in security and privacy testing?', 'QA turns security and privacy requirements into testable abuse cases, validates authorization and data handling, supports threat modeling, and ensures the right specialists review high-risk areas.', 'I added negative authorization checks and PII masking validation to our API regression after a privacy review highlighted data-exposure risk.', 'QA should not claim to replace dedicated security testing or a formal security assessment.'],
    ['Root-cause analysis', 'How do you conduct a useful root-cause analysis after an escaped defect?', 'Focus on the system: requirement clarity, design, implementation, test layer, data, environment, review, and release controls. Agree actions with owners and verify they work.', 'For one escaped calculation defect, the RCA led to an example-based acceptance-criteria template and unit tests for the rounding boundary that had been missed.', 'A root-cause meeting that ends with “test more” has not found a useful corrective action.'],
    ['Tool selection', 'How do you decide whether to build or buy a test tool?', 'Compare the business need, integration fit, skill availability, licensing, support, security, lock-in, total maintenance cost, and time to value. Pilot with a measurable success criterion.', 'We selected a managed cloud grid after a time-boxed comparison showed lower maintenance and better device coverage than maintaining our own fleet.', 'Do not choose tools only because they are popular or familiar.'],
    ['Team capacity', 'How do you plan QA capacity across manual, automation, and support work?', 'Use product risk, release calendar, support demand, maintenance load, and team capability to plan. Protect capacity for quality debt and incident learning, not only feature testing.', 'I used historical support and regression data to make hidden maintenance work visible during sprint planning.', 'Capacity planning should make trade-offs explicit rather than silently overloading QA.'],
    ['Quality objectives', 'How do you set quality objectives or OKRs?', 'Choose outcome-oriented measures such as lower escaped critical defects, faster reliable feedback, reduced flaky rate, or improved recovery time. Pair each metric with an owner and initiative.', 'Our objective to reduce flaky rate included baseline, owner rotation, weekly review, and a target below 2%, which made improvement actionable.', 'Avoid targets that encourage gaming, such as “write 500 automated tests.”'],
    ['Distributed teams', 'How do you maintain quality standards across distributed teams?', 'Document working agreements, keep decisions visible, use asynchronous reviews and dashboards, schedule risk discussions, and build shared templates and examples.', 'I recorded short test-strategy walkthroughs and used a common release checklist so teams in different time zones could make consistent decisions.', 'Process should improve clarity, not create meeting overload.'],
    ['Executive communication', 'How do you explain a quality risk to non-technical leadership?', 'Lead with customer and business impact, then give the evidence, options, mitigation, owner, and decision deadline in plain language.', 'I reported an integration risk as “orders may be delayed for a subset of customers” rather than leading with a stack trace; that enabled a quick decision on a feature flag.', 'Do not bury the decision request under implementation detail.']
  ]);

  ensureThirty('qa-metrics', 'MET', 'QA Metrics', [
    ['Defect density', 'How do you use defect density responsibly?', 'Use it as a comparable trend against a stable size measure, then investigate changes with release context and severity—not as a universal score for a team.', 'I used defect density alongside change volume and severity to identify a risky component after a major rewrite.', 'Metric comparisons are misleading when scope, reporting behavior, or product maturity changes.'],
    ['Defect leakage', 'What does defect leakage tell you?', 'Leakage shows defects found later than the intended test stage; it helps identify gaps in requirement, unit, integration, or system testing.', 'I tracked leakage by feature and stage to justify more API contract coverage for a service with repeated integration escapes.', 'Leakage is a learning signal, not a reason to blame the test phase.'],
    ['Defect rejection ratio', 'How do you interpret a high defect rejection ratio?', 'Inspect rejection reasons: unclear requirement, duplicate report, environment issue, expected behavior, or poor reproduction. Improve the source rather than chasing a lower number.', 'We reduced invalid defects by adding reproducible steps, logs, and expected-versus-actual templates to defect reports.', 'A low ratio achieved by reporting fewer defects is not an improvement.'],
    ['Test execution', 'How do you report test execution progress?', 'Report completed, passed, failed, blocked, not run, and risk-weighted coverage with the reason for blocked work. Separate progress from release readiness.', 'For a release dashboard, I showed critical-flow execution separately from the broad regression total so leadership could see what mattered.', 'A high execution percentage can hide untested high-risk scope.'],
    ['Pass and fail trend', 'Why is pass percentage insufficient as a release metric?', 'It shows test outcomes but not severity, risk coverage, blocked scope, flaky tests, or whether tests are meaningful. Use it with defect and coverage context.', 'I paired pass trend with open critical defects and unexecuted risk areas so a 95% pass rate could not be misread as a green release.', 'Never present pass rate as proof that the product is defect-free.'],
    ['Automation coverage', 'How do you measure automation coverage?', 'Measure coverage of agreed risk areas or requirements by reliable automated checks, not merely the number of automated cases. Segment by layer and execution frequency.', 'I reported automated coverage for critical user journeys, APIs, and browser compatibility separately because their cost and confidence differed.', 'Raw automation percentage rewards easy checks and can ignore the most valuable risks.'],
    ['Automation ROI', 'How do you demonstrate automation ROI?', 'Compare build and maintenance cost with manual effort saved, feedback speed, defects caught earlier, release frequency, and operational stability.', 'After moving smoke checks into CI, we measured a 70% reduction in manual pre-release effort and faster defect feedback to developers.', 'ROI must include ongoing maintenance, not only initial savings.'],
    ['Test coverage', 'What is the difference between test-case coverage and risk coverage?', 'Test-case coverage counts planned tests; risk coverage shows whether material failure modes are protected. Senior reporting should emphasize risk coverage.', 'I replaced a long test-case count report with a risk matrix that highlighted untested payment and migration failure modes.', 'Counting tests without mapping them to requirements or risks creates false confidence.'],
    ['Requirement coverage', 'How do you calculate requirement coverage?', 'Map approved requirements and acceptance criteria to at least one meaningful test, then identify missing, blocked, changed, or intentionally excluded items.', 'I used an RTM to expose two acceptance criteria with no negative-path tests before release.', 'Coverage is only useful if the requirement is testable and the linked test is substantive.'],
    ['Escaped defects', 'How do you learn from escaped defects?', 'Classify by impact, feature, root cause, detection opportunity, and recurrence. Prioritize prevention work where customer impact and repeat frequency are highest.', 'A monthly escape review showed that authorization issues were recurring, so we added a reusable role matrix to API tests.', 'Do not use escaped-defect counts to punish teams; use them to improve the system.'],
    ['Defect aging', 'How do you use defect aging?', 'Track how long defects remain open by severity, owner, state, and reason. Aging identifies unresolved risk, decision bottlenecks, and quality debt.', 'We flagged aging critical defects in release reviews, which made ownership and accepted risk explicit.', 'An old low-priority cosmetic issue should not be treated like an aging security defect.'],
    ['MTTR', 'What does MTTR mean for QA?', 'Mean time to restore measures how quickly service returns after an incident. QA improves it through diagnostics, runbooks, rollback validation, safe release design, and reproducible evidence.', 'After improving failure artifacts and deployment smoke checks, incident triage became much faster because engineering had screenshots, logs, and request IDs immediately.', 'MTTR is a cross-functional operational measure, not a QA-only metric.'],
    ['Flaky rate', 'How do you define flaky-test rate?', 'Track inconsistent outcomes for the same test on unchanged code and environment, including passed-after-retry tests. Segment root causes and treat the rate as automation health.', 'We published a flaky-rate trend by suite and owner; that made unstable tests visible before they eroded trust in CI.', 'Do not classify known product intermittency as a test flake without evidence.'],
    ['Release quality', 'What is a useful release-quality scorecard?', 'Combine customer impact, escaped defects, rollback or hotfix rate, critical-path test health, support signals, and reliability after release. Use trends, not a single magic score.', 'I used a release scorecard to compare release health over quarters and identify where quality gates needed strengthening.', 'A composite score can hide serious risk if the components are not visible.'],
    ['Quality gates', 'What makes a quality gate effective?', 'It is fast, objective, tied to a meaningful risk, visible to owners, and paired with a clear exception process. Automate gates where possible.', 'We enforced API contracts and a stable smoke suite on pull requests, while longer browser checks ran asynchronously with a defined release cutoff.', 'A gate that is slow or noisy becomes a bypass habit.'],
    ['Risk assessment', 'How do you quantify risk for testing decisions?', 'Use impact and likelihood, then add change size, dependency complexity, detectability, customer exposure, and rollback difficulty. Keep the model simple enough to apply consistently.', 'I scored release areas in refinement and used the highest scores to drive pairwise, negative, and integration coverage.', 'A complicated scoring model that nobody uses is worse than a simple transparent one.'],
    ['Trend analysis', 'Why are quality trends more useful than single-release snapshots?', 'Trends reveal direction, seasonality, and the effect of interventions. Compare like with like and annotate major architecture or process changes.', 'A six-month trend showed test duration rising with each release, which justified parallelization and removal of duplicated UI checks.', 'Do not infer causation from one movement in a chart.'],
    ['Lead time', 'How does lead time relate to quality?', 'Long lead time can delay feedback and increase integration risk. QA can improve it with early clarification, fast checks, self-service data, and reliable environments.', 'By moving contract tests to pull requests, we found integration issues days earlier and reduced rework near the release window.', 'Short lead time is not healthy if it is achieved by skipping essential checks.'],
    ['Test effectiveness', 'How do you assess whether your tests are effective?', 'Look at defects caught by layer, mutation or change detection where available, escape patterns, false positives, test maintenance cost, and whether tests influence decisions.', 'We retired several noisy UI checks after analysis showed they never caught defects that were not already caught by faster API tests.', 'More tests do not automatically mean better detection.'],
    ['Mean time to detect', 'How do you reduce mean time to detect issues?', 'Create fast CI feedback, good monitoring, actionable alerts, clear ownership, correlation IDs, and failure artifacts. Put the most likely and highest-impact checks earliest.', 'We added request IDs to API failure reports and cut the time from failed test to actionable developer investigation.', 'An alert that fires often without context increases noise rather than detection quality.'],
    ['Cost of quality', 'How do prevention, appraisal, and failure cost affect QA planning?', 'Spend strategically on prevention and fast appraisal to reduce expensive internal and external failure. Use incidents and rework data to focus investment.', 'A recurring production issue justified time for requirement examples and contract tests because the cost of hotfixes and support was much higher.', 'Do not assume all prevention work has the same value.'],
    ['Metrics anti-patterns', 'Which metric anti-patterns do you avoid?', 'Avoid targets that reward volume over value, hidden denominator changes, unsegmented averages, and metrics without a decision or owner. Always add context.', 'I replaced “number of bugs found” with severity, source, trend, and prevention actions to avoid rewarding low-quality reporting.', 'Metrics should drive learning and decisions, not performance theater.'],
    ['Executive dashboard', 'How would you design a QA dashboard for executives?', 'Show a concise release health narrative: customer impact, top risks, quality-gate status, unresolved decisions, delivery trend, and actions. Provide drill-down separately.', 'My dashboard used one red-amber-green summary with evidence links, then a detailed page for engineering leads.', 'Executives need decision-ready context, not a wall of test-case counts.'],
    ['SLOs and SLAs', 'How do SLOs and SLAs influence testing?', 'SLOs define target reliability and performance; SLAs define commitments. Turn them into performance, resilience, monitoring, and release-validation checks.', 'For an API latency objective, we added load thresholds and post-deploy monitoring to validate the customer-facing target.', 'Do not test only average response time when percentile and error-rate targets matter.'],
    ['Quality baseline', 'Why establish a quality baseline before an improvement initiative?', 'A baseline proves whether a change worked and avoids relying on perception. Capture current flakiness, duration, escapes, triage time, and coverage before intervening.', 'Before refactoring waits, we captured 30 days of flaky failures and could show the improvement after the change.', 'Without a baseline, teams often claim improvement they cannot demonstrate.'],
    ['Continuous improvement', 'How do you turn quality metrics into continuous improvement?', 'Review a small set regularly, select one cause to address, assign an owner, experiment, and measure the outcome. Close the loop publicly.', 'We used a weekly flaky-test review with a rotating owner and saw steady improvement instead of occasional cleanup campaigns.', 'Dashboards without action ownership quickly become ignored.'],
    ['Data quality', 'How do you measure data quality in testing?', 'Track completeness, validity, uniqueness, consistency, timeliness, and referential integrity against agreed business rules.', 'For a migration, we reconciled counts, duplicate rates, nulls, and key relationships before approving cutover.', 'Data quality needs business rules; technical row counts alone are insufficient.'],
    ['Customer signals', 'How do customer support signals improve QA metrics?', 'Correlate support volume, common journeys, severity, churn risk, and customer segments with release and defect data to focus tests on real pain.', 'Support tickets highlighted a confusing export flow, so we added accessibility and file-content checks that standard regression had missed.', 'Customer signals need triage; not every ticket represents a product defect.'],
    ['Metric ownership', 'Who should own quality metrics?', 'Quality is shared: QA curates testing signals, engineering owns code health, product owns customer outcomes, and leadership owns investment and trade-offs.', 'I assigned clear owners to each dashboard action so metrics led to decisions rather than generic observations.', 'A metrics dashboard owned only by QA cannot fix cross-functional problems.'],
    ['Metric review cadence', 'How often should quality metrics be reviewed?', 'Use operational signals daily or per release, delivery trends weekly, and strategic outcomes monthly or quarterly. Match cadence to the speed of the decision.', 'We reviewed deployment health daily, suite stability weekly, and escaped-defect themes monthly.', 'Reviewing everything daily creates noise; reviewing incidents quarterly is too slow.']
  ]);

  ensureThirty('tricky-questions', 'TRK', 'Tricky Questions', [
    ['Selenium waits', 'Why should you avoid mixing implicit and explicit waits?', 'They can combine unpredictably and make timeout behavior hard to diagnose. Keep implicit wait at zero or a minimal agreed value and use explicit waits for specific conditions.', 'In a legacy suite, removing a global implicit wait made failures faster and exposed the exact element condition that needed a proper explicit wait.', 'The trade-off is writing intentional waits versus accepting hidden timing behavior.'],
    ['Stale element', 'Why does StaleElementReferenceException happen and how do you fix it?', 'The DOM changed after the element reference was obtained. Re-locate after the update, wait for the new state, and avoid caching dynamic elements.', 'I fixed a flaky cart test by waiting for the AJAX update and locating the row by product ID after every quantity change.', 'Retrying clicks without understanding the DOM change hides the real synchronization issue.'],
    ['Selenium vs Playwright', 'When would Selenium still be a better choice than Playwright?', 'Choose Selenium when language ecosystem, existing investment, grid compatibility, browser coverage, or team expertise make it the lower-risk choice. Choose based on product and operating context.', 'I kept a mature Selenium suite for a Java enterprise product while using Playwright for a new TypeScript service where tracing and contexts added clear value.', 'Tool choice is an engineering decision, not a popularity contest.'],
    ['Browser navigation', 'What is the practical difference between get() and navigate().to()?', 'Both load a URL; navigate() additionally exposes history operations. Use the API that makes the intent clear and do not overstate behavioral differences.', 'In browser-history tests, I used navigate().back() and forward() after a clearly defined initial get().', 'The real concern is reliable page state, not memorizing trivia.'],
    ['Driver cleanup', 'Why is quit() preferred over close() in test teardown?', 'quit() ends the WebDriver session and closes all windows; close() only closes the current window. Use quit() to prevent orphaned browser processes.', 'A Jenkins agent had resource exhaustion until we enforced quit() in an always-run teardown and added stale-process monitoring.', 'Multi-window tests may use close() during the flow, but teardown still needs quit().'],
    ['Element lookup', 'When should you use findElements() instead of findElement()?', 'Use findElements() for optional presence, collection operations, and count checks because it returns an empty list rather than throwing when no match exists.', 'I used findElements() in a reusable optional-banner handler to avoid exception-driven control flow.', 'Do not use it to mask a required element that should cause a clear failure.'],
    ['ThreadLocal', 'Why is ThreadLocal important for parallel Selenium tests?', 'WebDriver is not thread-safe. ThreadLocal gives each parallel test thread its own driver instance and prevents sessions from overwriting each other.', 'After introducing ThreadLocal and isolated data, we safely reduced a regression suite from three hours to under one hour.', 'ThreadLocal does not solve shared test data or non-thread-safe reports by itself.'],
    ['POM assertions', 'Should assertions live in Page Objects?', 'Keep primary business assertions in tests so intent remains visible; pages should expose state or domain actions. Small component-level state checks can be acceptable when they improve reuse.', 'I moved broad assertions out of a page class and kept only a reusable “is loaded” signal, making test failures easier to understand.', 'Overly pure rules can create duplication; favor readable boundaries.'],
    ['Java static', 'Why can static state make automation flaky?', 'Static mutable state is shared across tests and threads, causing order dependence and leakage. Keep constants static, but scope mutable resources to the test or thread.', 'A shared static token caused parallel API tests to invalidate each other until we stored auth state per test context.', 'Static is not inherently bad; uncontrolled mutable static state is.'],
    ['Java equality', 'What is the difference between == and equals() in Java?', '== compares primitive values or object references; equals() compares logical content when the class implements it. Use Objects.equals for null-safe content comparison.', 'I have seen test failures caused by comparing two distinct String objects with == after data was loaded from JSON.', 'Always mention null handling when answering this question.'],
    ['HashMap', 'Why is HashMap not inherently thread-safe?', 'Concurrent updates can race and corrupt assumptions. Use synchronization, ConcurrentHashMap, or avoid shared mutation depending on the use case.', 'For a parallel result collector, I used ConcurrentHashMap with clear ownership instead of a shared HashMap.', 'Thread safety is about the access pattern, not only the collection type.'],
    ['LinkedHashMap', 'When is LinkedHashMap useful in testing?', 'It preserves insertion order, making data-driven output, API payload comparisons, and diagnostic reports deterministic and readable.', 'I used LinkedHashMap to retain CSV column order in validation error messages.', 'Do not choose it when sorted order or concurrent access is the real requirement.'],
    ['Strings', 'StringBuilder or StringBuffer: which should you use?', 'Use StringBuilder for efficient single-threaded mutation; use StringBuffer only when synchronized mutation is actually required. String remains immutable.', 'In test-data generation, StringBuilder kept repeated construction efficient without adding unnecessary synchronization.', 'Thread safety should be intentional, not assumed from a class name.'],
    ['PUT vs PATCH', 'How do PUT and PATCH differ in API testing?', 'PUT generally replaces a resource representation and is idempotent; PATCH applies a partial change and its idempotency depends on the operation. Validate the documented contract.', 'I tested a PATCH endpoint with missing, null, and unchanged fields to prove it did not erase unrelated data.', 'Do not rely on method names alone—confirm implementation semantics.'],
    ['401 vs 403', 'Differentiate 401 and 403 with a testing example.', '401 means authentication is absent or invalid; 403 means the caller is authenticated but lacks permission. Test both the status and that the protected action did not occur.', 'I used a viewer token and an expired token against the same delete endpoint to validate the two contracts distinctly.', 'Do not expose sensitive permission details in error responses.'],
    ['Request specification', 'Why use RequestSpecification in REST Assured?', 'It centralizes base URI, headers, auth, logging, and timeouts so tests stay focused on their individual contract.', 'A shared request spec removed repeated token and base URL setup across hundreds of API tests.', 'Keep test-specific headers and assertions visible rather than hiding all behavior in a base class.'],
    ['Wrong 200 response', 'How do you test an API that returns 200 but wrong data?', 'Validate business fields, schema, types, ordering where promised, authorization scope, and side effects—not only status code.', 'A customer search API returned 200 with another tenant’s record; a data-isolation assertion caught the issue before release.', 'Status-only tests create a dangerous false green.'],
    ['Token refresh', 'How do you test expired-token behavior?', 'Use controlled short-lived or mocked tokens, verify the error contract, refresh flow where applicable, and ensure protected actions are not partially applied.', 'I added a token-expiry test to a nightly suite because CI time made natural expiry impractical during PR runs.', 'Do not use real production secrets or unstable shared tokens in tests.'],
    ['Idempotency', 'What is idempotency and why does it matter in API tests?', 'An idempotent operation can be repeated without changing the final state beyond the first application. It matters for retries, network failures, and duplicate requests.', 'For order creation, we verified an idempotency key prevented duplicate orders when a client retried after a timeout.', 'Do not assume POST is never idempotent or PUT always is without reading the contract.'],
    ['SQL joins', 'What is a common mistake with LEFT JOIN filters?', 'Filtering the right table in the WHERE clause can turn a LEFT JOIN into an INNER JOIN. Put optional-side criteria in the join condition when unmatched rows must remain.', 'I caught a migration reconciliation query that silently excluded missing child rows because of a WHERE filter on the right table.', 'Test queries with null and unmatched data, not only happy-path joins.'],
    ['CTE', 'When is a CTE better than a subquery?', 'Use a CTE to improve readability in multi-step logic or to name intermediate results. Verify performance with the execution plan rather than assuming a CTE is faster.', 'I used named CTEs to make a duplicate-detection reconciliation query auditable for non-DB specialists.', 'Readability is valuable, but large data sets still need plan inspection.'],
    ['Window functions', 'ROW_NUMBER, RANK, and DENSE_RANK—what is the difference?', 'ROW_NUMBER assigns unique sequential numbers, RANK leaves gaps after ties, and DENSE_RANK does not leave gaps. Choose based on the business ranking rule.', 'I used ROW_NUMBER partitioned by customer to identify duplicate migration records while preserving the most recent row.', 'Explain partitions and ordering; ranking functions without them are incomplete.'],
    ['NULL', 'Why is NULL tricky in SQL tests?', 'NULL represents unknown or absent values, not an empty string or zero. Comparisons require IS NULL or IS NOT NULL, and aggregates and joins handle it differently.', 'A nullability migration bug surfaced only when we tested optional addresses, not the default seeded data.', 'Never compare NULL with equals in SQL.'],
    ['Git recovery', 'When should you use git reset versus git revert?', 'Use reset to rewrite local history when it is safe; use revert to create a compensating commit in shared history. Prefer the safer shared-history option on team branches.', 'After a bad shared merge, we used revert so the correction remained transparent and did not disrupt teammates.', 'Do not force-push rewritten shared history without an agreed process.'],
    ['Jenkins failure', 'How do you troubleshoot a test that fails only in Jenkins?', 'Compare environment, browser, data, timing, secrets, resources, and artifacts. Start with logs, screenshots, trace or video, and the exact CI command.', 'A CI-only failure was caused by a smaller default viewport; setting an explicit window size and retaining screenshots confirmed the fix.', 'Do not add sleeps before collecting evidence.'],
    ['Docker', 'Why use Docker for test execution?', 'Docker makes browser, dependency, and tool versions reproducible, supports isolated parallel nodes, and reduces machine-specific setup drift.', 'We ran Selenium Grid containers in CI to keep Chrome and driver versions consistent across agents.', 'Containers still require capacity, networking, secrets, and artifact management.'],
    ['Quality ownership', 'Is quality owned only by QA?', 'No. QA enables and validates quality, but product, engineering, operations, and leadership all own decisions that affect customer quality.', 'I made quality shared by adding testability and quality-gate ownership to team working agreements rather than treating QA as the final gatekeeper.', 'A shared ownership statement needs concrete practices to be real.'],
    ['Test coverage', 'Can 100% test coverage mean a product is safe?', 'No. Coverage measures execution of code or requirements, not the quality of assertions, data, integrations, or missing scenarios. Use it as one signal.', 'A fully covered service still had an escaped authorization path because the tests never used a second tenant.', 'High coverage without meaningful negative cases can be misleading.'],
    ['Retries', 'When are retries appropriate in automation?', 'Use bounded retries only for classified transient conditions and retain every failure artifact. A passed retry should still be visible as instability.', 'We allowed one retry for known grid disconnects but logged the test for investigation if it passed on the retry.', 'Retries should never hide deterministic assertion or product failures.']
  ]);

  ensureThirty('project-resume', 'PRJ', 'Project & Resume', [
    ['Project overview', 'Tell me about your current or most recent project.', 'Give the product, users, domain, team, delivery model, stack, quality strategy, your role, and one measurable impact in a concise story.', 'I frame my project story around the business workflow first, then explain where I owned automation, API validation, CI, and release quality.', 'Keep the introduction relevant to the role instead of reciting every technology.'],
    ['Architecture', 'Describe your automation framework architecture.', 'Explain the layers: configuration, driver or context lifecycle, pages or clients, test data, utilities, reporting, and CI. Emphasize why each boundary exists.', 'In my framework, DriverFactory and configuration handled lifecycle, pages owned UI actions, API clients seeded data, and reports captured diagnostics.', 'Architecture should reflect the product’s needs, not a list of design patterns.'],
    ['Responsibilities', 'What were your day-to-day responsibilities?', 'Describe ownership across refinement, test design, automation, API and DB validation, defect triage, CI health, release support, and mentoring.', 'I owned a customer onboarding area end to end: requirement review, risk matrix, automation maintenance, release sign-off evidence, and defect trend follow-up.', 'Differentiate your contribution from work performed by the wider team.'],
    ['Team size', 'What was your team structure and how did you work with it?', 'State the team composition, dependencies, ceremonies, and how quality decisions were made. Highlight collaboration with developers, product, DevOps, and support.', 'My squad had product, backend, frontend, and QA roles; I joined refinement, partnered on contracts, and shared release risk in demos and planning.', 'Team size matters less than showing effective cross-functional work.'],
    ['Automation percentage', 'How do you explain your automation percentage?', 'Give the percentage with the scope and definition behind it—critical flows, regression scope, layer, and execution frequency—then explain its value.', 'I reported automation separately for API regression and browser critical paths so leadership understood both speed and real customer coverage.', 'Never quote an automation percentage without explaining what it covers.'],
    ['Test volume', 'How do you discuss the number of test cases you owned?', 'Give a credible range and explain risk coverage, execution cadence, and maintenance approach. Volume is useful only with context.', 'I owned roughly 250 automated checks but focused the interview story on the 40 critical-path checks that gated releases.', 'Large counts do not impress if the suite is slow or unreliable.'],
    ['Framework choice', 'Why did you choose your framework design?', 'Explain how the design met the team’s language, product architecture, skill, reporting, parallelism, and maintenance requirements.', 'We chose Java, TestNG, REST Assured, Selenium, POM, and JSON data because it matched existing services and team capability while supporting CI parallelization.', 'Avoid presenting the choice as the only valid framework.'],
    ['CI/CD', 'How was automation integrated into CI/CD?', 'Explain which tests ran on pull request, deployment, nightly, and release candidate; mention artifacts, gates, notifications, and flaky-test handling.', 'I split smoke, API contracts, and full regression by feedback need, then published Allure links and failure evidence directly in the pipeline.', 'A CI story should include what happened when a check failed.'],
    ['API testing', 'What was your API testing contribution?', 'Describe the APIs, authentication, request and response validation, chaining, negative cases, schema checks, data setup, and CI usage.', 'I built reusable API clients for onboarding flows that seeded UI data quickly and validated backend side effects without slow UI setup.', 'Do not say only that you tested status codes.'],
    ['Database testing', 'How did you validate database behavior?', 'Explain the supported read access, queries, data lineage, migration or CRUD validation, and how you kept tests independent of brittle schema details.', 'I used unique test IDs to trace UI-created orders through API and DB validation, while keeping most UI tests independent of direct database coupling.', 'Avoid exposing confidential schema or production data in an interview.'],
    ['Biggest defect', 'Tell me about the most important defect you found.', 'Use situation, customer impact, discovery method, evidence, collaboration, resolution, and preventive action. Choose a story that shows judgment, not only technical luck.', 'I found a role-based access gap during negative API testing; we stopped the release, fixed authorization, and added a reusable permission matrix.', 'Do not exaggerate impact or claim sole credit for a team outcome.'],
    ['Automation challenge', 'What was your biggest automation challenge?', 'Describe the constraint, root cause, options considered, implementation, and measurable result.', 'A third-party iframe made checkout tests unstable, so I combined API setup, targeted frame waits, and trace artifacts; failure triage time dropped sharply.', 'The answer should demonstrate systematic problem solving, not frustration.'],
    ['Biggest contribution', 'What is your biggest contribution to the project?', 'Choose an outcome you personally drove, explain why it mattered, how you influenced others, and the evidence that it improved delivery or customer quality.', 'I introduced a reliable PR smoke suite that cut feedback from hours to minutes and reduced late integration defects.', 'Avoid describing a contribution only as “I wrote many test cases.”'],
    ['Production issue', 'Describe a production issue you helped resolve.', 'Lead with customer impact and stabilization, then describe diagnostics, root cause, corrective action, prevention, and what you learned.', 'During an authentication outage, I helped correlate failed synthetic checks with token-service latency, supported rollback validation, and added post-deploy alerts.', 'Be clear about your role and protect confidential incident details.'],
    ['Performance improvement', 'How have you improved test performance?', 'Measure the baseline, remove redundant UI work, improve setup, parallelize safely, and validate that detection quality remains intact.', 'I replaced shared UI setup with API data creation and reduced a critical suite from 90 to 25 minutes.', 'Performance without stable test data or capacity planning can create new flakiness.'],
    ['Execution reduction', 'How did you reduce regression execution time?', 'Use risk tiers, parallelism, lower-layer checks, and removal of duplicate coverage. Explain the before and after with reliability evidence.', 'I introduced a 12-minute deployment smoke suite and moved the expanded browser matrix to release candidates and nightlies.', 'Do not cut tests blindly to improve a dashboard number.'],
    ['Flaky reduction', 'How did you reduce flaky tests?', 'Show the failure classification, fixes, quarantine policy, and measured improvement.', 'I used repeat-run analytics, locator review, data isolation, and CI artifacts to reduce flakiness from 15% to below 3%.', 'Retries alone are not a flaky-test strategy.'],
    ['Leadership', 'How have you demonstrated leadership without being a manager?', 'Show influence through standards, mentoring, risk communication, ownership of a quality initiative, or unblocking delivery.', 'I coordinated a cross-team release readiness checklist and made ownership visible, which reduced last-minute handoffs and ambiguity.', 'Leadership stories need an outcome, not only a meeting you attended.'],
    ['Cross-team dependency', 'How did you handle a dependency owned by another team?', 'Make the dependency, interface, risk, owner, fallback, and deadline visible early. Validate contracts and communicate decisions clearly.', 'For an upstream API change, I created contract checks, agreed a sandbox schedule, and escalated with a clear customer-impact statement when the date slipped.', 'Do not wait until the release day to surface a dependency risk.'],
    ['Security', 'How did you include security or privacy in your quality work?', 'Discuss authorization, sensitive-data masking, negative cases, secure test data, and collaboration with security specialists.', 'I added role and tenant isolation tests plus log masking checks after a privacy review identified customer-data exposure risk.', 'Avoid claiming formal penetration testing unless you actually performed it.'],
    ['Accessibility', 'How did you test accessibility or usability?', 'Explain practical checks such as keyboard navigation, labels, contrast, focus, error messages, and support for assistive technologies, plus the standards or specialists involved.', 'I added keyboard and label checks to our critical onboarding flow and partnered with design on clear validation messages.', 'Accessibility is not limited to a one-time automated scan.'],
    ['Data migration', 'Describe your role in a data migration or release cutover.', 'Explain reconciliation scope, pre- and post-cutover checks, sampled business rules, rollback readiness, and the evidence used for sign-off.', 'I prepared count, null, duplicate, and referential-integrity queries for a migration and reported the exceptions before business approval.', 'Migration testing needs both technical and business validation.'],
    ['Difficult feedback', 'Tell me about difficult feedback you gave or received.', 'Describe the behavior or evidence, the respectful conversation, agreed action, and improvement. Keep the focus on learning.', 'I gave feedback on unstable locator practices using repeat-run data, then paired on a stable selector strategy that the team adopted.', 'Avoid making the other person the villain.'],
    ['Career narrative', 'Why are you looking for a new role?', 'Keep it positive: explain the kind of product, technical challenge, ownership, or growth you want next and connect it to the role.', 'I am looking for a role where I can combine hands-on automation with senior quality strategy across product teams.', 'Never focus the answer on complaints about a previous employer.'],
    ['Why hire', 'Why should we hire you for this senior QA/SDET role?', 'Summarize the role-relevant mix: risk-based quality thinking, hands-on automation, API and data depth, CI reliability, and collaborative leadership backed by outcomes.', 'I close with one concise example of improving feedback speed and stability because it demonstrates both technical and delivery impact.', 'Tailor this answer to the employer rather than using a generic pitch.'],
    ['Interview questions', 'What questions would you ask the interviewer about the project?', 'Ask about quality ownership, architecture, release cadence, customer risk, environments, test data, CI feedback, and how success is measured.', 'I ask which quality problem the team most wants solved in the first six months so I can understand the real role expectations.', 'Questions should show curiosity and judgment, not only benefits or tooling.'],
    ['Resume metrics', 'How do you include metrics on your resume credibly?', 'Use numbers that you can explain: scope, baseline, action, time frame, and outcome. Prefer impact metrics over a list of tools.', 'I state “reduced regression time from 3 hours to 55 minutes through parallel execution and API setup,” then prepare the detailed story for interviews.', 'Never invent or round metrics so aggressively that you cannot defend them.'],
    ['Failure story', 'Tell me about an approach that did not work and what you changed.', 'Own the assumption, show the evidence that challenged it, explain the pivot, and finish with the new practice and result.', 'I initially added retries for CI instability, then repeat-run data showed shared test data was the cause; we removed the retries after fixing isolation.', 'A failure story should demonstrate learning, not avoid accountability.']
  ]);

  ensureThirty('mock-interviews', 'MCK', 'Mock Interviews', [
    ['Manual round', 'Mock: Explain your risk-based testing approach for a new checkout feature.', 'Start with payment and data risks, define critical paths and negative cases, select the right layers, prepare test data, and communicate residual risk before release.', 'In practice, I would pair a small browser smoke journey with payment API contracts, authorization checks, and a monitored release plan.', 'Keep the answer structured and time-boxed like a real interview response.'],
    ['Manual round', 'Mock: How do smoke, sanity, regression, and retesting differ?', 'Smoke validates build stability, sanity validates a focused change, retesting validates a specific fix, and regression checks existing behavior after change.', 'I would give a release example so the interviewer sees when I use each type rather than only definitions.', 'Avoid using the terms interchangeably.'],
    ['Selenium round', 'Mock: Draw and explain Selenium WebDriver architecture.', 'Explain client library, W3C WebDriver protocol, browser driver, browser, and where version or remote-grid problems occur.', 'I would connect the diagram to a real driver-version failure that we solved through controlled browser images.', 'A diagram is useful only when you explain the operational impact.'],
    ['Selenium round', 'Mock: How do you design reliable XPath and CSS locators?', 'Prefer stable user-facing attributes or test IDs, scope to a stable component, avoid positional selectors, and collaborate with developers when testability is missing.', 'I would mention replacing a brittle nth-child XPath with a data-testid and how that reduced maintenance.', 'Do not present absolute XPath as a default strategy.'],
    ['Selenium round', 'Mock: Explain waits and dynamic-element handling.', 'Use explicit waits for the intended state, avoid fixed sleeps, handle DOM rerenders by re-locating elements, and capture evidence when conditions time out.', 'I would describe an AJAX cart example where waiting for a total update was more reliable than waiting for the button alone.', 'A wait should represent user-visible readiness, not arbitrary time.'],
    ['Selenium round', 'Mock: How do you handle windows, frames, uploads, downloads, and Shadow DOM?', 'Switch contexts deliberately, wait for expected handles or frames, use absolute paths for uploads, configure a unique download directory, and use Selenium 4 shadow-root APIs for open roots.', 'I would show that teardown returns to default content and cleans test files where needed.', 'Context switching errors are often misdiagnosed as locator problems.'],
    ['Selenium round', 'Mock: How do you run Selenium tests in parallel?', 'Use ThreadLocal WebDriver, isolated data, unique artifacts, capacity-aware Grid or containers, and reliable teardown.', 'I would mention measuring flakiness and node capacity while increasing worker count gradually.', 'Parallel execution magnifies shared-state problems.'],
    ['Java round', 'Mock: Explain OOP concepts through a test framework.', 'Use encapsulation for page internals, abstraction through WebDriver interfaces, inheritance sparingly for shared fixtures, and polymorphism for browser or strategy implementations.', 'I would avoid forcing every OOP concept into inheritance and discuss composition as the default for reusable services.', 'Examples make OOP answers credible.'],
    ['Java round', 'Mock: Compare List, Set, Map, Comparable, and Comparator.', 'Choose List for ordered duplicates, Set for uniqueness, Map for key-value lookup, Comparable for natural order, and Comparator for external or multiple sort orders.', 'I would tie each collection to test data, window handles, or report aggregation.', 'State the ordering and duplicate behavior, not only class names.'],
    ['Java round', 'Mock: Write a duplicate-character solution and explain complexity.', 'Use a LinkedHashMap frequency count for O(n) time and deterministic output, then handle case, spaces, and null input according to the requirement.', 'I would narrate the edge cases before coding because interviewers look for judgment as well as syntax.', 'Do not jump straight to a solution without defining input behavior.'],
    ['Framework round', 'Mock: Explain your POM and framework boundaries.', 'Pages own UI interactions, tests own business flow and assertions, utilities stay narrow, configuration and lifecycle are centralized, and data setup is isolated.', 'I would describe how this boundary made a UI change affect one page class rather than dozens of tests.', 'Avoid a BasePage that becomes a dumping ground.'],
    ['Framework round', 'Mock: Explain TestNG listeners, retry, DataProvider, and parallel execution.', 'Listeners capture lifecycle and artifacts, retries are bounded diagnostic tools, DataProvider supplies variation, and parallel tests need isolation and ThreadLocal resources.', 'I would explain the policy that a passed-after-retry test remains visible in reports.', 'Do not use every TestNG feature simply because it exists.'],
    ['Framework round', 'Mock: Explain Maven’s role in an automation framework.', 'Maven manages dependencies, build lifecycle, profiles, plugins, reports, and CI commands. It makes the test environment reproducible.', 'I would mention separate profiles for local, QA, and CI plus a focused command for smoke tests.', 'Avoid hard-coding environment behavior in pom.xml without controlled configuration.'],
    ['Framework round', 'Mock: Explain data-driven and hybrid frameworks.', 'Data-driven separates data from test flow; hybrid combines POM, data, utilities, reporting, and CI while maintaining clear responsibilities.', 'I would choose JSON or API builders for most versioned test data and use Excel only where business users maintain inputs.', 'A hybrid framework should not mean every pattern in one project.'],
    ['Playwright round', 'Mock: Why use user-facing Playwright locators?', 'getByRole, getByLabel, and similar locators align with accessible behavior and reduce coupling to CSS structure. Use test IDs when semantics are not unique.', 'I would explain how locator quality drove accessibility conversations with the frontend team.', 'Auto-waiting does not make a bad selector good.'],
    ['Playwright round', 'Mock: How do fixtures and storage state improve Playwright tests?', 'Fixtures make dependencies explicit and isolated; storage state reuses controlled authentication without logging in through the UI every test.', 'I would create separate states for roles and refresh them through a secure setup rather than sharing mutable accounts.', 'Do not let a shared storage state carry test mutations between cases.'],
    ['Playwright round', 'Mock: How do trace viewer and network interception help?', 'Trace provides timeline, DOM, action, console, and network evidence; interception supports deterministic failure or third-party scenarios without making every test a mock.', 'I would retain traces on first failure and use real integration smoke checks for critical contracts.', 'Over-mocking can hide the integration defects users actually see.'],
    ['API round', 'Mock: Explain an API test strategy for a microservice.', 'Cover contract, auth, validation, negative paths, state changes, idempotency, performance, dependencies, observability, and deployment feedback at the right layers.', 'I would start with endpoint and consumer risk rather than a generic list of HTTP methods.', 'API testing is not only sending requests and checking status codes.'],
    ['API round', 'Mock: Explain REST Assured framework design.', 'Centralize request and response specs, endpoint clients, models, auth, data builders, schema checks, reporting, and cleanup so tests stay readable.', 'I would show how endpoint clients made a new service testable without copying setup into every test.', 'Keep test assertions visible instead of hiding all behavior in helpers.'],
    ['API round', 'Mock: How do you use Postman and Newman in CI?', 'Collections organize requests and scripts; environments hold safe configuration; Newman runs collections with reports and failure exit codes in CI.', 'I would explain where Postman is a fast collaboration tool and where code-based REST Assured is better for maintainable frameworks.', 'Never commit secrets into collection exports.'],
    ['SQL round', 'Mock: Explain joins, CTEs, and window functions with QA examples.', 'Use joins for relationships, CTEs for readable multi-step logic, and windows for ranking, deduplication, or sequence comparisons without collapsing rows.', 'I would describe a migration reconciliation query that identifies duplicate records with ROW_NUMBER.', 'Always state how nulls and unmatched records affect your query.'],
    ['Database round', 'Mock: How do you validate UI or API data against a database?', 'Use unique test IDs, validate the business-critical persisted fields and relationships, allow documented eventual consistency, and avoid coupling all UI tests to schema internals.', 'I would use API setup and DB verification for a small set of critical flows, not every browser assertion.', 'Direct database validation should complement—not replace—user-facing checks.'],
    ['DevOps round', 'Mock: Describe your Git workflow and conflict-resolution approach.', 'Use short-lived branches, pull or fetch, review, rebase or merge according to team policy, resolve conflicts with context, test the result, and keep shared history safe.', 'I would explain a real conflict where I coordinated with the author instead of guessing intent from code.', 'Do not use reset or force-push on shared branches casually.'],
    ['DevOps round', 'Mock: Design a Jenkins pipeline for QA automation.', 'Use stages for build, static checks, unit, API contracts, smoke, reporting, artifacts, notification, and controlled longer regression. Keep credentials secure and failures actionable.', 'I would split PR and nightly suites to preserve fast feedback while retaining broad coverage.', 'A pipeline should state what happens after failure, not merely list stages.'],
    ['DevOps round', 'Mock: How do Docker and cloud grids help test execution?', 'Containers make versions reproducible; cloud or grid execution enables browser and device scale. Manage capacity, artifacts, network, and secure credentials.', 'I would compare managed grid cost with self-hosted maintenance before choosing a solution.', 'Scale is useful only if data and tests are truly isolated.'],
    ['Senior round', 'Mock: A critical defect is found before release. Talk through your decision.', 'Confirm impact and scope, gather evidence, propose mitigation or rollback options, clarify owner, and communicate the residual risk and deadline.', 'I would mention feature flags and monitored partial release only if the safety criteria were clear.', 'QA should not make a unilateral business decision.'],
    ['Senior round', 'Mock: How do you make quality visible to leadership?', 'Use a concise decision-focused dashboard with critical risk, coverage, unresolved defects, release gates, automation health, and the action needed.', 'I would bring an example where better risk communication changed release scope before customer impact occurred.', 'Do not overload leadership with raw execution detail.'],
    ['HR round', 'Mock: Tell me about a conflict with a developer.', 'Use a calm situation-action-result story: share evidence, understand the constraint, agree a practical next step, and focus on the customer outcome.', 'I would describe resolving a disagreement about defect severity through logs and reproduction rather than escalating emotion.', 'Never present the developer as the problem.'],
    ['HR round', 'Mock: Why should we hire you?', 'Connect hands-on automation, risk-based quality, API and data depth, reliable CI practices, and collaborative leadership to the role’s needs.', 'I would close with one measurable improvement I delivered and why that matters for the team hiring me.', 'Tailor the answer to the company and role.'],
    ['Final mixed round', 'Mock: Give a two-minute summary of your senior QA value.', 'State your quality mindset, technical strengths, business impact, collaboration style, and the kind of problem you want to solve next.', 'I practice a clear opening that can lead naturally into project, framework, or leadership follow-up questions.', 'A concise confident summary is more memorable than a long tool inventory.']
  ]);

  ensureThirty('hr-behavioral', 'HRX', 'HR & Behavioral', [
    ['Introduction', 'Tell me about yourself.', 'Give a present-past-future story: current senior QA/SDET scope, relevant experience and outcomes, then why this opportunity is the right next step.', 'I lead with hands-on automation and quality ownership, then mention one measurable delivery improvement before connecting to the role.', 'Keep the answer under two minutes and relevant to the job.'],
    ['Career move', 'Why are you changing jobs?', 'Frame the change positively around product challenge, growth, broader ownership, domain interest, or technical environment.', 'I focus on the quality problems I want to solve next rather than frustration with my current employer.', 'Never use this answer to criticize people or companies.'],
    ['Hiring pitch', 'Why should we hire you?', 'Match your evidence to the role: senior test strategy, reliable automation, API and data testing, CI/CD, and collaborative influence.', 'I use one concrete result—such as reducing feedback time or flaky rate—to prove the claim.', 'A generic list of tools is weaker than an outcome-based pitch.'],
    ['Strengths', 'What are your strengths?', 'Choose two or three relevant strengths and support each with a brief example, such as risk communication, systematic debugging, or framework ownership.', 'I describe how structured failure triage made the team trust CI again, rather than simply saying I am detail-oriented.', 'Avoid vague adjectives without evidence.'],
    ['Development area', 'What is a weakness or development area you are working on?', 'Choose a genuine, non-critical gap, explain the action you are taking, and show progress. Keep it honest and role-safe.', 'I discuss becoming more concise in executive updates and the one-page risk format I now use.', 'Do not use a fake strength disguised as a weakness.'],
    ['Developer conflict', 'Describe a conflict with a developer.', 'State the shared goal, evidence, conversation, agreed experiment or decision, and result. Keep the tone respectful.', 'I resolved a severity disagreement by reproducing the issue with production-like data and agreeing a feature-flag mitigation.', 'Do not turn a collaborative problem into a personal story.'],
    ['Manager conflict', 'How do you handle disagreement with your manager?', 'Clarify intent, bring facts and options, listen to constraints, agree the decision owner, and commit once a decision is made.', 'I have raised capacity risk with data, proposed scope options, and supported the final prioritization even when it differed from my first preference.', 'Escalation is not a substitute for a respectful direct conversation.'],
    ['Pressure', 'How do you handle pressure before a major release?', 'Create visibility, prioritize critical risks, protect focus, communicate early, and avoid shortcuts that create a larger incident later.', 'Before a tight release, I ran focused smoke and integration checks, tracked blockers hourly, and made residual risk explicit to stakeholders.', 'Working longer without prioritization is not a strategy.'],
    ['Tight deadline', 'Tell me about delivering quality under a tight deadline.', 'Explain the triage, scope reduction, risk-based test plan, communication, and result. Show that you managed risk rather than pretending everything was tested.', 'I reduced scope to critical paths, used API checks for speed, and documented what could not be validated before the date.', 'Do not claim complete coverage when time did not allow it.'],
    ['Leadership', 'How do you demonstrate leadership?', 'Show influence, ownership, mentoring, standards, or decision support without relying on a job title.', 'I led a flaky-test reduction initiative by using evidence, coordinating owners, and publishing the stability trend.', 'Leadership should create a durable improvement, not only a one-time rescue.'],
    ['Mentoring', 'How do you mentor junior team members?', 'Assess the gap, pair on real work, give actionable feedback, transfer ownership, and recognize progress.', 'I paired with a junior engineer on API test design, then had them own a service smoke suite and present its results.', 'Mentoring is not doing the task for someone else.'],
    ['Salary expectations', 'How do you answer salary-expectation questions?', 'Give a researched range if appropriate, state that role scope and total package matter, and keep the discussion professional and flexible.', 'I focus first on fit and responsibilities, then share a market-informed range when the recruiter needs it.', 'Do not negotiate from guesswork or disclose information you do not want to share.'],
    ['Career goals', 'What are your career goals?', 'Connect near-term goals to deeper quality ownership, technical breadth, mentoring, or product impact, and show how the role supports them.', 'I want to remain hands-on while growing into broader quality strategy and cross-team platform work.', 'Avoid goals that make the role sound like a short stop.'],
    ['Failure', 'Tell me about a failure and what you learned.', 'Own your part, describe impact without drama, explain corrective action, and show the durable practice that changed afterward.', 'I describe initially using retries for a flaky suite, then learning to fix data isolation and measure instability instead.', 'A good answer includes accountability and prevention.'],
    ['Achievement', 'What achievement are you most proud of?', 'Choose a meaningful customer or delivery outcome, then explain your role, collaboration, and evidence of improvement.', 'I am proud of making release smoke checks reliable enough that engineers trusted them during deployment decisions.', 'Do not present team success as individual work.'],
    ['Feedback', 'How do you receive constructive feedback?', 'Listen without defensiveness, clarify examples, identify an action, follow up on progress, and thank the person for helping you improve.', 'After feedback that my defect reports were too detailed, I adopted a concise summary-first template and got faster developer responses.', 'Do not say you have never received negative feedback.'],
    ['Prioritization', 'How do you prioritize competing work?', 'Use customer impact, urgency, dependencies, risk, effort, and commitments; make trade-offs visible and renegotiate scope when needed.', 'I used a simple risk board to balance release testing, support triage, and framework maintenance in a busy sprint.', 'Silent prioritization creates surprise for stakeholders.'],
    ['Ambiguity', 'How do you work with ambiguous requirements?', 'Turn ambiguity into examples, questions, assumptions, and testable acceptance criteria; validate early with product and engineering.', 'I used example mapping to expose missing permission rules before implementation, preventing late rework.', 'Do not begin test execution while pretending an unclear rule is clear.'],
    ['Ethics', 'How would you handle pressure to hide a quality risk?', 'State the risk factually, protect customer and company interests, use the established escalation path, and document the decision without exaggeration.', 'I would present the impact and mitigation options to the accountable release owner rather than silently changing results.', 'Integrity is essential; never manipulate evidence to meet a deadline.'],
    ['Collaboration', 'How do you build trust with developers and product managers?', 'Be early, specific, reliable, and solution-oriented. Share evidence, help improve testability, and celebrate defect prevention rather than only detection.', 'I earned trust by joining refinement, providing reproducible reports, and making CI failures easier to act on.', 'Trust is built through consistent behavior, not a single process meeting.'],
    ['Remote work', 'How do you stay effective in a distributed team?', 'Use clear written updates, visible decisions, thoughtful handoffs, focused meetings, and shared artifacts such as dashboards and runbooks.', 'I use concise async risk updates and record important walkthroughs so different time zones can participate without blocking delivery.', 'Do not equate online presence with effective communication.'],
    ['Work style', 'What working environment helps you do your best work?', 'Describe conditions that support quality—clear priorities, collaborative engineering, feedback, autonomy with accountability, and customer focus—without sounding inflexible.', 'I work best where quality questions can be raised early and ownership is shared across the team.', 'Keep the answer compatible with the role rather than listing demands.'],
    ['Customer focus', 'How do you keep customer impact in mind in QA?', 'Connect technical risk to user journeys, accessibility, data safety, support signals, and business outcomes. Prioritize what customers experience most.', 'I use production support themes to improve regression coverage for workflows that create real customer pain.', 'Do not reduce customer focus to only happy-path UI checks.'],
    ['Change management', 'How do you handle changing priorities?', 'Reassess risk and commitments, communicate the impact, protect critical quality work, and update the plan rather than resisting change or silently dropping work.', 'When a release date moved forward, I reset the test plan around the critical paths and documented deferred coverage.', 'Change is normal; hidden risk is the problem.'],
    ['Ownership', 'Describe a time you took ownership beyond your assigned task.', 'Explain the gap you noticed, why it mattered, the collaboration you built, and the improvement that lasted.', 'I created a CI failure-triage guide after seeing repeated confusion, then used it to reduce duplicate investigations across the team.', 'Ownership should be constructive and aligned with team goals.'],
    ['Resilience', 'How do you recover after a difficult incident or failed release?', 'Separate immediate stabilization from learning, ask for support, take the corrective action, and avoid carrying blame into future collaboration.', 'After a difficult release, I helped run the RCA, created actionable follow-ups, and checked their effectiveness in the next releases.', 'Resilience is not ignoring the emotional or operational impact.'],
    ['Influence', 'How do you influence without authority?', 'Bring evidence, understand other priorities, propose low-friction experiments, communicate benefits, and make success visible.', 'I persuaded teams to adopt stable test IDs by showing maintenance data and piloting the approach on one critical feature.', 'Authority is less effective than shared evidence and a practical path forward.'],
    ['Learning', 'How do you keep your QA skills current?', 'Learn through product incidents, engineering practices, targeted courses, proof-of-concepts, code reviews, and teaching others. Prioritize learning tied to real team needs.', 'I use a small learning backlog connected to upcoming architecture changes so new skills improve delivery rather than remaining theoretical.', 'Avoid naming many courses without showing applied learning.'],
    ['Closing', 'What would your colleagues say about working with you?', 'Choose believable qualities supported by behavior: reliable, calm under pressure, structured, collaborative, and focused on customer impact.', 'My colleagues would say I make quality risk visible early and help turn failures into practical improvements.', 'Keep the answer grounded and invite a reference-style follow-up.']
  ]);

  // Rebuild the broad revision deck so the new senior material is eligible for Top 200 study sessions.
  var sources = [];
  Object.keys(defined_sections).forEach(function (key) {
    if (key !== 'top-200' && key !== 'top-50-senior') {
      var section = defined_sections[key];
      if (section.questions) sources.push.apply(sources, section.questions);
    }
  });
  var priority = sources.filter(function (item) { return item.importance === 'must' || item.importance === 'senior'; });
  var revisionSource = priority.length >= 200 ? priority : sources;
  defined_sections['top-200'].questions = Array.from({ length: 200 }, function (_, index) {
    var source = revisionSource[index % revisionSource.length];
    var copy = Object.assign({}, source);
    copy.id = 'TOP' + String(index + 1).padStart(3, '0');
    copy.category = 'Top 200 Must-Know';
    copy.topic = source.category + ' - ' + source.topic;
    copy.importance = 'must';
    return copy;
  });
})();
